  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single batch be split across multiple vats (e.g., dyed partly in vat 1 and partly in vat 2), or must each batch be assigned to exactly one vat for its entire processing?"
  ],
  "rationale": "The response asks for a single policy choice regarding batch assignment, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a batch moves from one vat to the next, does it have to wait until the next vat is completely free, or can it start in the next vat as soon as that vat finishes its current job (i.e., a standard flow-shop where each vat processes one batch at a time)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the scheduling constraint for moving batches between vats."
}

{
  "action": "question",
